#define NN_ACTION_EVIDENCE 1
#define NN_BATCH_FEATURES 1
// Learned simultaneous-action capture-the-flag search. CPU only.
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <functional>
#include <iostream>
