using namespace std;
struct Unit { int id, team, x, y, hp, flag, respawn_at; };      // 阵亡时 x = y = -1
struct Flag { int id; string status; int x, y, holder, return_at; };
struct Event { string type; vector<int> args; };                // 各类事件的字段见 RULES.md

struct Game {
    // 开局信息（INIT 块）
    int teams = 0, me = 0, size = 0, turns = 0, hp = 0, damage = 0, respawn = 0, flag_return = 0, flag_cooldown = 0;
    vector<string> map;                  // map[y][x]：'#' 墙，'.' 空地
    vector<pair<int, int>> bases;        // 各阵营基地中心，基地是以它为中心的 3×3
    vector<pair<int, int>> spots;        // 全部旗点
    // 每回合更新（TURN 块）
    int turn = 0;
    vector<int> score;
    vector<Unit> units;
    vector<Flag> flags;
    vector<Event> events;                // 上一回合发生的事件
};

// 读一个块。读到 INIT 时继续读到 TURN 块结束。返回 false 表示输入结束。
bool read_turn(Game& g) {
    string w;
    while (cin >> w) {
        if (w == "INIT") {
            cin >> g.teams >> g.me >> g.size >> g.turns >> g.hp >> g.damage >> g.respawn >> g.flag_return >> g.flag_cooldown;
        } else if (w == "MAP") {
            g.map.assign(g.size, "");
            for (auto& row : g.map) cin >> row;
        } else if (w == "BASES") {
            int k; cin >> k; g.bases.resize(k);
            for (auto& b : g.bases) cin >> b.first >> b.second;
        } else if (w == "SPOTS") {
            int k; cin >> k; g.spots.resize(k);
            for (auto& s : g.spots) cin >> s.first >> s.second;
        } else if (w == "TURN") {
            cin >> g.turn;
        } else if (w == "SCORE") {
            g.score.resize(g.teams);
            for (auto& s : g.score) cin >> s;
        } else if (w == "UNITS") {
            int k; cin >> k; g.units.resize(k);
            for (auto& u : g.units) { string tag; cin >> tag >> u.id >> u.team >> u.x >> u.y >> u.hp >> u.flag >> u.respawn_at; }
        } else if (w == "FLAGS") {
            int k; cin >> k; g.flags.resize(k);
            for (auto& f : g.flags) { string tag; cin >> tag >> f.id >> f.status >> f.x >> f.y >> f.holder >> f.return_at; }
        } else if (w == "EVENTS") {
            int k; cin >> k; g.events.assign(k, {});
            string line; getline(cin, line);
            for (auto& e : g.events) {
                getline(cin, line);
                istringstream in(line);
                string tag; in >> tag >> e.type;
                for (int v; in >> v;) e.args.push_back(v);
            }
        } else if (w == "END") {
            return true;
        }
    }
    return false;
}

using State=Game;
struct Order {int move=0, action=-1;}; // -1 pickup, -2 wait, -3 drop
struct World {
    State g;
    vector<vector<pair<int,int>>> spawn;
    uint64_t rng;
    explicit World(State state,uint64_t seed):g(move(state)),rng(seed?seed:1) {
        g.turn=0;
        for(auto bc:g.bases){
            vector<pair<int,int>> b;
            for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++)b.emplace_back(bc.first+dx,bc.second+dy);
            stable_sort(b.begin(),b.end(),[&](auto a,auto b){
                auto key=[&](auto p){return pair(abs(p.first-g.size/2)+abs(p.second-g.size/2),abs(p.first-bc.first)+2*abs(p.second-bc.second));};
                return key(a)<key(b);
            });spawn.push_back(b);
        }
    }
    pair<int,int> point(int i)const{return {g.units[i].x,g.units[i].y};}
    bool wall(pair<int,int> p)const{return p.first<0||p.second<0||p.first>=g.size||p.second>=g.size||g.map[p.second][p.first]=='#';}
    bool hit(pair<int,int> a,pair<int,int> b)const{
        int dx=b.first-a.first,dy=b.second-a.second;
        if(abs(dx)+abs(dy)>2)return false;
        if(abs(dx)==2)return !wall({a.first+dx/2,a.second});
        if(abs(dy)==2)return !wall({a.first,a.second+dy/2});
        if(abs(dx)==1&&abs(dy)==1)return !wall({a.first+dx,a.second})||!wall({a.first,a.second+dy});
        return true;
    }
    void step(const vector<Order>& orders){
        ++g.turn;g.events.clear();int nu=g.units.size();
        for(auto& f:g.flags)if((f.status=="dropped"||f.status=="cooldown")&&f.return_at<=g.turn){
            vector<pair<int,int>> free;
            for(auto p:g.spots){bool taken=false;for(auto& ff:g.flags)if(ff.status=="home"&&ff.x==p.first&&ff.y==p.second)taken=true;if(!taken)free.push_back(p);}
            if(free.empty())free=g.spots;
            rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;
            auto p=free[rng%free.size()];f.x=p.first;f.y=p.second;f.status="home";f.holder=f.return_at=-1;
            g.events.push_back({"return",{f.id}});
        }
        bool immune[45]={};int occupied[2500];fill(occupied,occupied+2500,-1);
        for(auto& u:g.units)if(u.x>=0)occupied[u.y*g.size+u.x]=u.id;
        for(auto& u:g.units)if(u.x<0&&u.respawn_at<=g.turn){
            for(auto p:spawn[u.team])if(occupied[p.second*g.size+p.first]<0){
                u.x=p.first;u.y=p.second;u.hp=g.hp;u.flag=u.respawn_at=-1;immune[u.id]=true;occupied[u.y*g.size+u.x]=u.id;
                g.events.push_back({"respawn",{u.id,u.x,u.y}});break;
            }
        }
        vector<pair<int,int>> start(nu),want(nu);int count[2500]={};bool blocked[45]={};
        int dx[5]={0,0,0,-1,1},dy[5]={0,-1,1,0,0};
        for(auto& u:g.units)if(u.x>=0){int i=u.id;start[i]=point(i);want[i]={u.x+dx[orders[i].move],u.y+dy[orders[i].move]};if(wall(want[i]))want[i]=start[i];count[want[i].second*g.size+want[i].first]++;}
        for(auto& u:g.units)if(u.x>=0){int i=u.id;auto p=want[i];if(count[p.second*g.size+p.first]>1)blocked[i]=true;int j=occupied[p.second*g.size+p.first];if(j>=0&&j!=i&&u.team!=g.units[j].team&&want[j]==start[i])blocked[i]=blocked[j]=true;}
        for(int rep=0;rep<nu;rep++){bool changed=false;for(auto& u:g.units)if(u.x>=0&&!blocked[u.id]&&want[u.id]!=start[u.id]){int j=occupied[want[u.id].second*g.size+want[u.id].first];if(j>=0&&(blocked[j]||want[j]==start[j])){blocked[u.id]=true;changed=true;}}if(!changed)break;}
        for(auto& u:g.units)if(u.x>=0){auto p=blocked[u.id]?start[u.id]:want[u.id];u.x=p.first;u.y=p.second;}
        vector<vector<int>> by(nu);
        for(auto& u:g.units)if(u.x>=0&&u.flag<0&&!immune[u.id]){int j=orders[u.id].action;if(j>=0&&j<nu&&g.units[j].x>=0&&g.units[j].team!=u.team&&!immune[j]&&hit(point(u.id),point(j))){by[j].push_back(u.id);g.events.push_back({"attack",{u.id,j}});}}
        for(auto& u:g.units)if(u.x>=0)u.hp-=g.damage*by[u.id].size();
        for(auto& u:g.units)if(u.x>=0&&u.hp<=0){
            vector<int> ev{u.id,u.x,u.y,u.flag,int(by[u.id].size())};ev.insert(ev.end(),by[u.id].begin(),by[u.id].end());g.events.push_back({"death",ev});
            if(u.flag>=0){auto& f=g.flags[u.flag];f.status="dropped";f.x=u.x;f.y=u.y;f.holder=-1;f.return_at=g.turn+g.flag_return;}
            u.x=u.y=-1;u.hp=0;u.flag=-1;u.respawn_at=g.turn+g.respawn;
        }
        for(auto& u:g.units)if(u.x>=0&&u.flag<0&&orders[u.id].action==-1){
            for(auto& f:g.flags)if((f.status=="home"||f.status=="dropped")&&f.x==u.x&&f.y==u.y){u.flag=f.id;f.status="carried";f.x=f.y=-1;f.holder=u.id;f.return_at=-1;g.events.push_back({"pickup",{u.id,f.id}});break;}
        }
        for(auto& u:g.units)if(u.x>=0&&u.flag>=0&&orders[u.id].action==-3){auto& f=g.flags[u.flag];f.status="dropped";f.x=u.x;f.y=u.y;f.holder=-1;f.return_at=g.turn+g.flag_return;g.events.push_back({"drop",{u.id,u.flag}});u.flag=-1;}
        for(auto& u:g.units)if(u.x>=0&&u.flag>=0&&abs(u.x-g.bases[u.team].first)<=1&&abs(u.y-g.bases[u.team].second)<=1){int fid=u.flag;auto& f=g.flags[fid];f.status="cooldown";f.x=f.y=-1;f.holder=-1;f.return_at=g.turn+g.flag_cooldown;u.flag=-1;g.score[u.team]++;g.events.push_back({"capture",{u.id,u.team,fid}});}
    }
    void dump()const{
        cout<<g.turn;for(int s:g.score)cout<<' '<<s;
        for(auto& u:g.units)cout<<' '<<u.x<<' '<<u.y<<' '<<u.hp<<' '<<u.flag<<' '<<u.respawn_at;
        for(auto& f:g.flags)cout<<' '<<f.status<<' '<<f.x<<' '<<f.y<<' '<<f.holder<<' '<<f.return_at;
        cout<<" |";for(auto& e:g.events){cout<<' '<<e.type;for(int a:e.args)cout<<' '<<a;cout<<';';}cout<<endl;
    }
};

