// Shared, public-observation-only features for offline learning and CPU inference.
// Standard C++20 only. All geometry is rebuilt from the public INIT block.
namespace learning {
constexpr int PF=112;
#ifdef RICH_VALUE
constexpr int VF=80+3*PF;
#else
constexpr int VF=80;
#endif
// Respawns are deterministic public information. Predict them before choosing
// commands, while leaving unknown flag refreshes to sampled rule transitions.
template<class G> G prepared(const G& input){
    G g=input;int n=g.size;std::vector<int> occupied(n*n,-1);
    for(auto& u:g.units)if(u.x>=0)occupied[u.y*n+u.x]=u.id;
    for(auto& u:g.units)if(u.x<0&&u.respawn_at>=0&&u.respawn_at<=g.turn){
        auto bc=g.bases[u.team];std::vector<std::pair<int,int>> cells;
        for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++)cells.push_back({bc.first+dx,bc.second+dy});
        std::stable_sort(cells.begin(),cells.end(),[&](auto a,auto b){auto key=[&](auto p){return std::pair(std::abs(p.first-n/2)+std::abs(p.second-n/2),std::abs(p.first-bc.first)+2*std::abs(p.second-bc.second));};return key(a)<key(b);});
        for(auto p:cells)if(occupied[p.second*n+p.first]<0){u.x=p.first;u.y=p.second;u.hp=g.hp;u.flag=-1;u.respawn_at=-1;occupied[u.y*n+u.x]=u.id;break;}
    }return g;
}
struct Geometry {
    int n=0,N=0;
    std::vector<short> distances;
    std::vector<std::array<int,5>> nb;
    std::vector<std::vector<int>> home;
    std::vector<std::array<int,3>> staging;
    int D(int a,int b)const{return a<0||b<0?100:distances[a*N+b];}
    int man(int a,int b)const{return a<0||b<0?100:std::abs(a%n-b%n)+std::abs(a/n-b/n);}
    template<class G> void init(const G& g){
        n=g.size;N=n*n;nb.resize(N);distances.assign(N*N,30000);
        const int dx[5]={0,0,0,-1,1},dy[5]={0,-1,1,0,0};std::vector<int> q(N);
        for(int p=0;p<N;p++)for(int m=0;m<5;m++){
            int x=p%n+dx[m],y=p/n+dy[m];nb[p][m]=x>=0&&x<n&&y>=0&&y<n&&g.map[y][x]!='#'?y*n+x:p;
        }
        for(int s=0;s<N;s++)if(g.map[s/n][s%n]!='#'){
            auto d=&distances[s*N];d[s]=0;int h=0,t=0;q[t++]=s;
            while(h<t){int p=q[h++];for(int m=1;m<5;m++){int z=nb[p][m];if(d[z]==30000){d[z]=d[p]+1;q[t++]=z;}}}
        }
        home.assign(g.teams,std::vector<int>(N,100));
        for(int team=0;team<g.teams;team++)for(int p=0;p<N;p++)for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++)
            home[team][p]=std::min(home[team][p],D(p,(g.bases[team].second+dy)*n+g.bases[team].first+dx));
        staging.resize(g.teams);
        for(int team=0;team<g.teams;team++){
            std::vector<std::pair<int,int>> order;
            for(auto s:g.spots){int q=s.second*n+s.first;order.push_back({home[team][q],q});}
            std::sort(order.begin(),order.end());
            for(int k=0;k<3;k++)staging[team][k]=k<int(order.size())?order[k].second:-1;
        }
    }
    template<class G> bool hit(const G& g,int a,int b)const{
        if(a<0||b<0||man(a,b)>2)return false;
        int dx=b%n-a%n,dy=b/n-a/n;
        if(std::abs(dx)==2)return g.map[a/n][a%n+dx/2]!='#';
        if(std::abs(dy)==2)return g.map[a/n+dy/2][a%n]!='#';
        if(std::abs(dx)==1&&std::abs(dy)==1)return g.map[a/n][a%n+dx]!='#'||g.map[a/n+dy][a%n]!='#';
        return true;
    }
    template<class U> int cell(const U& u)const{return u.x<0?-1:u.y*n+u.x;}
    template<class G> std::array<float,PF> policy(const G& g,int id,int move,int old=-1)const{
        std::array<float,PF> f{};auto& u=g.units[id];int p=cell(u),team=u.team;
        if(p<0){f[0]=-1;return f;}int z=nb[p][move];
        f[0]=u.hp/100.f;f[1]=u.flag>=0;f[2]=g.teams/15.f;f[3]=(g.turns-g.turn)/400.f;
        f[4]=(z%n-p%n);f[5]=(z/n-p/n);f[6]=move==0;f[7]=move!=0&&z==p;
        f[8]=home[team][z]/24.f;f[9]=home[team][p]-home[team][z];f[10]=home[team][z]==0;
        f[11]=(g.bases[team].first-z%n)/24.f;f[12]=(g.bases[team].second-z/n)/24.f;
        f[13]=old>=0&&old!=p&&z-p==p-old;f[14]=old>=0&&z==old;f[15]=man(z,(n/2)*n+n/2)/24.f;
        std::vector<std::pair<int,int>> flags;
        for(auto& flag:g.flags){int q=-1;if(flag.x>=0&& (flag.return_at<0||flag.return_at>g.turn))q=flag.y*n+flag.x;else if(flag.holder>=0)q=cell(g.units[flag.holder]);if(q>=0)flags.push_back({D(p,q),flag.id});}
        std::sort(flags.begin(),flags.end());
        for(int j=0;j<4;j++){
            int at=16+j*9;if(j>=int(flags.size())){f[at+4]=-1;continue;}
            auto& flag=g.flags[flags[j].second];int q=flag.x>=0?flag.y*n+flag.x:cell(g.units[flag.holder]);
            f[at]=(q%n-z%n)/16.f;f[at+1]=(q/n-z/n)/16.f;f[at+2]=D(z,q)/24.f;f[at+3]=D(p,q)-D(z,q);
            f[at+4]=flag.holder<0?1:g.units[flag.holder].team==team?2:3;
            f[at+5]=flag.holder<0?home[team][q]/24.f:g.units[flag.holder].hp/100.f;
            int ally=100,enemy=100;for(auto& e:g.units)if(e.x>=0&&e.flag<0&&e.id!=id){int d=D(cell(e),q);if(e.team==team)ally=std::min(ally,d);else enemy=std::min(enemy,d);}
            f[at+6]=(std::min(30,ally)-D(z,q))/24.f;f[at+7]=(std::min(30,enemy)-D(z,q))/24.f;
            f[at+8]=flag.return_at>=0?(flag.return_at-g.turn)/15.f:1;
        }
        std::vector<std::pair<int,int>> enemies;
        for(auto& e:g.units)if(e.team!=team&&e.x>=0)enemies.push_back({D(p,cell(e)),e.id});
        std::sort(enemies.begin(),enemies.end());
        for(int j=0;j<4;j++){
            int at=52+j*9;if(j>=int(enemies.size())){f[at+3]=-1;continue;}
            auto& e=g.units[enemies[j].second];int q=cell(e);
            f[at]=(q%n-z%n)/12.f;f[at+1]=(q/n-z/n)/12.f;f[at+2]=D(z,q)/16.f;
            f[at+3]=e.hp/100.f;f[at+4]=e.flag>=0;f[at+5]=hit(g,z,q);f[at+6]=D(p,q)-D(z,q);
            int support=0,threat=0;
            for(auto& a:g.units)if(a.x>=0&&a.flag<0&&a.id!=id){int d=man(cell(a),q);if(d<=3){if(a.team==team)support++;else if(a.team==e.team)threat++;}}
            f[at+7]=support/3.f;f[at+8]=threat/3.f;
        }
        int j=0;for(int k=team*3;k<team*3+3;k++)if(k!=id){
            int at=88+j++*6;auto& a=g.units[k];int q=cell(a);if(q<0){f[at+3]=-1;continue;}
            f[at]=(q%n-z%n)/16.f;f[at+1]=(q/n-z/n)/16.f;f[at+2]=D(z,q)/20.f;f[at+3]=a.hp/100.f;f[at+4]=a.flag>=0;f[at+5]=z==q;
        }
        for(int j=0;j<3&&staging[team][j]>=0;j++){int at=100+j*4,q=staging[team][j];f[at]=(q%n-z%n)/24.f;f[at+1]=(q/n-z/n)/24.f;f[at+2]=D(z,q)/24.f;f[at+3]=D(p,q)-D(z,q);}
        for(float& v:f)v=std::clamp(v,-4.f,4.f);return f;
    }
    template<class G> std::array<std::array<float,PF>,5> policyMoves(const G& g,int id,int old=-1)const{
        // The same origin, nearest objects and support counts serve all five
        // moves. Keep the scalar implementation as the independent reference.
        std::array<std::array<float,PF>,5> out;out.fill(policy(g,id,0,old));
        auto& u=g.units[id];int p=cell(u),team=u.team;if(p<0)return out;
        std::vector<std::pair<int,int>> flags,enemies;
        for(auto& flag:g.flags){int q=-1;if(flag.x>=0&&(flag.return_at<0||flag.return_at>g.turn))q=flag.y*n+flag.x;else if(flag.holder>=0)q=cell(g.units[flag.holder]);if(q>=0)flags.push_back({D(p,q),flag.id});}
        for(auto& e:g.units)if(e.team!=team&&e.x>=0)enemies.push_back({D(p,cell(e)),e.id});
        std::sort(flags.begin(),flags.end());std::sort(enemies.begin(),enemies.end());
        std::array<int,4> fq{},ally{},enemy{};
        for(int j=0;j<4&&j<int(flags.size());j++){
            auto& f=g.flags[flags[j].second];fq[j]=f.x>=0?f.y*n+f.x:cell(g.units[f.holder]);ally[j]=enemy[j]=100;
            for(auto& e:g.units)if(e.x>=0&&e.flag<0&&e.id!=id){int d=D(cell(e),fq[j]);if(e.team==team)ally[j]=std::min(ally[j],d);else enemy[j]=std::min(enemy[j],d);}
        }
        for(int m=1;m<5;m++){
            auto& f=out[m];int z=nb[p][m];
            f[4]=z%n-p%n;f[5]=z/n-p/n;f[6]=0;f[7]=z==p;
            f[8]=home[team][z]/24.f;f[9]=home[team][p]-home[team][z];f[10]=home[team][z]==0;
            f[11]=(g.bases[team].first-z%n)/24.f;f[12]=(g.bases[team].second-z/n)/24.f;
            f[13]=old>=0&&old!=p&&z-p==p-old;f[14]=old>=0&&z==old;f[15]=man(z,(n/2)*n+n/2)/24.f;
            for(int j=0;j<4&&j<int(flags.size());j++){
                int at=16+j*9,q=fq[j];f[at]=(q%n-z%n)/16.f;f[at+1]=(q/n-z/n)/16.f;
                f[at+2]=D(z,q)/24.f;f[at+3]=D(p,q)-D(z,q);
                f[at+6]=(std::min(30,ally[j])-D(z,q))/24.f;f[at+7]=(std::min(30,enemy[j])-D(z,q))/24.f;
            }
            for(int j=0;j<4&&j<int(enemies.size());j++){
                int at=52+j*9,q=cell(g.units[enemies[j].second]);f[at]=(q%n-z%n)/12.f;f[at+1]=(q/n-z/n)/12.f;
                f[at+2]=D(z,q)/16.f;f[at+5]=hit(g,z,q);f[at+6]=D(p,q)-D(z,q);
            }
            int j=0;for(int k=team*3;k<team*3+3;k++)if(k!=id){int at=88+j++*6,q=cell(g.units[k]);if(q<0)continue;
                f[at]=(q%n-z%n)/16.f;f[at+1]=(q/n-z/n)/16.f;f[at+2]=D(z,q)/20.f;f[at+5]=z==q;
            }
            for(int j=0;j<3&&staging[team][j]>=0;j++){
                int at=100+j*4,q=staging[team][j];f[at]=(q%n-z%n)/24.f;f[at+1]=(q/n-z/n)/24.f;f[at+2]=D(z,q)/24.f;f[at+3]=D(p,q)-D(z,q);
            }
            for(float& v:f)v=std::clamp(v,-4.f,4.f);
        }return out;
    }
    template<class G> std::array<float,VF> value(const G& g,int team)const{
        std::array<float,VF> f{};
        f[0]=g.teams/15.f;f[1]=(g.turns-g.turn)/400.f;f[2]=g.score[team]/30.f;
        int others=0,leader=0;for(int i=0;i<g.teams;i++)if(i!=team){others+=g.score[i];leader=std::max(leader,g.score[i]);}
        f[3]=others/float((g.teams-1)*30);f[4]=(g.score[team]-leader)/20.f;f[5]=n/49.f;
        for(int k=0;k<3;k++){
            auto& u=g.units[team*3+k];int p=cell(u),at=8+k*12;
            f[at]=u.hp/100.f;f[at+1]=u.flag>=0;f[at+2]=p>=0?home[team][p]/24.f:1;f[at+3]=p<0?(u.respawn_at-g.turn)/10.f:0;
            int closest=100,adv=100,near=0,weak=0,support=0;
            for(auto& flag:g.flags)if(flag.x>=0){int q=flag.y*n+flag.x,d=D(p,q),en=100;for(auto& e:g.units)if(e.team!=team&&e.x>=0&&e.flag<0)en=std::min(en,D(cell(e),q));if(d<closest){closest=d;adv=d-en;}}
            for(auto& e:g.units)if(e.x>=0&&e.flag<0&&e.id!=u.id){int d=man(p,cell(e));if(e.team!=team&&d<=4){near++;weak+=e.hp<=34;}else if(e.team==team&&d<=4)support++;}
            f[at+4]=std::min(30,closest)/24.f;f[at+5]=std::clamp(adv,-24,24)/24.f;f[at+6]=near/6.f;f[at+7]=weak/3.f;f[at+8]=support/2.f;
            f[at+9]=p>=0?man(p,(n/2)*n+n/2)/24.f:1;
            f[at+10]=p>=0?(p%n-g.bases[team].first)/24.f:0;f[at+11]=p>=0?(p/n-g.bases[team].second)/24.f:0;
        }
        std::vector<std::pair<int,int>> flags;
        for(auto& flag:g.flags){int q=flag.x>=0?flag.y*n+flag.x:flag.holder>=0?cell(g.units[flag.holder]):-1;flags.push_back({q<0?100:home[team][q],flag.id});}
        std::sort(flags.begin(),flags.end());
        for(int j=0;j<8;j++){
            int at=44+j*4;if(j>=int(flags.size())){f[at]=-1;continue;}auto& flag=g.flags[flags[j].second];
            int q=flag.x>=0?flag.y*n+flag.x:flag.holder>=0?cell(g.units[flag.holder]):-1;
            f[at]=flag.holder<0?(flag.x>=0?1:0):g.units[flag.holder].team==team?2:3;
            f[at+1]=q>=0?home[team][q]/24.f:1;f[at+2]=flag.holder>=0?g.units[flag.holder].hp/100.f:0;
            f[at+3]=flag.holder>=0&&q>=0?home[g.units[flag.holder].team][q]/24.f:flag.return_at>=0?(flag.return_at-g.turn)/15.f:0;
        }
#ifdef RICH_VALUE
        // Preserve relative enemy geometry and wall-aware attack lines for each
        // squad member, rather than reducing tactical positions to enemy counts.
        for(int k=0;k<3;k++){auto p=policy(g,team*3+k,0);std::copy(p.begin(),p.end(),f.begin()+80+k*PF);}
#endif
        for(float& v:f)v=std::clamp(v,-4.f,4.f);return f;
    }
};
}

#define OPPONENT_HEADS 11
