// Learned policy priors + value-guided search over simultaneous joint actions.
// Opponents are sampled before our candidate action is evaluated, so the
// search cannot give either side access to the other's submitted command.
#ifndef OPPONENT_HEADS
#define OPPONENT_HEADS 1
#endif
#ifndef OPPONENT_ACTIONS
#define OPPONENT_ACTIONS 0
#endif
#ifndef NN_JOINT_BELIEF
#define NN_JOINT_BELIEF 0
#endif
#ifndef NN_LEADER_OBJECTIVE
#define NN_LEADER_OBJECTIVE 0
#endif
#ifndef NN_BATCH_FEATURES
#define NN_BATCH_FEATURES 0
#endif
#ifndef NN_ACTION_EVIDENCE
#define NN_ACTION_EVIDENCE 0
#endif
struct Planner {
    using Prob=std::array<float,5>;
    static constexpr int NN=OPPONENT_HEADS,E=NN+5,AK=OPPONENT_ACTIONS,NO=NN*(1+AK);
    static_assert(AK==0||AK==4);
    learning::Geometry geo;
    std::vector<int> previous;
    std::vector<bool> newLife;int preparedTurn=-1;
    std::array<std::array<std::array<float,E>,2>,15> evidence{};
    std::array<std::array<Prob,E>,45> lastExperts{};
    std::array<std::array<Prob,E>,45> workingExperts{};
    std::array<std::array<float,E>,45> headPosterior{};
    std::array<std::array<std::array<std::array<float,AK>,NN>,5>,45> actionForecast{};
    decltype(actionForecast) lastActionForecast{};
    std::array<int,15> sampledHeads{};
    std::array<int,45> lastClass{};
    uint64_t rng=0xD1B54A32D192ED03ull;
    std::chrono::steady_clock::time_point deadline;
    using Joint=std::array<int,3>;
    struct Candidate {Joint moves{};std::array<int,3> actions{{-1,-1,-1}};float prior=0,value=-1e9f;};
    template<int F> static float dot(const float* x,const float* w){
        // Four independent reductions let ordinary -O2 exploit CPU vector
        // instructions without architecture flags or a numerical runtime.
        float a=0,b=0,c=0,d=0;int i=0;
        for(;i+3<F;i+=4){a+=x[i]*w[i];b+=x[i+1]*w[i+1];c+=x[i+2]*w[i+2];d+=x[i+3]*w[i+3];}
        float s=(a+b)+(c+d);for(;i<F;i++)s+=x[i]*w[i];return s;
    }
    template<int F,int H,int Z> float infer(const std::array<float,F>& x,const float* w0,const float* b0,const float* w1,const float* b1,const float* w2,const float* b2)const{
        float h[H],z[Z];
        for(int j=0;j<H;j++)h[j]=std::max(0.f,b0[j]+dot<F>(x.data(),w0+j*F));
        for(int j=0;j<Z;j++)z[j]=std::max(0.f,b1[j]+dot<H>(h,w1+j*H));
        return b2[0]+dot<Z>(z,w2);
    }
    float potential(const Game& g,int team)const{
        float phi=0;for(int k=0;k<3;k++){auto& u=g.units[team*3+k];int p=geo.cell(u);if(p>=0){phi+=u.hp*.00025f;if(u.flag>=0)phi+=.45f*std::exp(-geo.home[team][p]/14.f);}}
        for(auto& f:g.flags)if(f.x>=0){int p=f.y*g.size+f.x,own=100,enemy=100;for(auto& u:g.units)if(u.x>=0&&u.flag<0){int d=geo.D(geo.cell(u),p);if(u.team==team)own=std::min(own,d);else enemy=std::min(enemy,d);}phi+=.15f*std::exp(-own/12.f)/(1+std::exp(std::clamp((own-enemy)/3.f,-20.f,20.f)));}
        return phi;
    }
    float value(const Game& g,int team)const{
        if(g.turn>g.turns)return 0;
        auto observation=learning::prepared(g);
        float v=infer<learning::VF,std::size(weights::value_b0),std::size(weights::value_b1)>(geo.value(observation,team),weights::value_w0,weights::value_b0,weights::value_w1,weights::value_b1,weights::value_w2,weights::value_b2);
#if VALUE_SHAPED
        v+=potential(g,team);
#endif
        return v;
    }
    Prob policy(const Game& g,int id)const{
        Prob p{};if(g.units[id].x<0){p[0]=1;return p;}
        std::array<std::array<float,learning::PF>,5> all{};
        if constexpr(NN_BATCH_FEATURES)all=geo.policyMoves(g,id,previous[id]);
        float maximum=-1e9,sum=0;
        for(int m=0;m<5;m++){
            auto f=NN_BATCH_FEATURES?all[m]:geo.policy(g,id,m,previous[id]);
            if(m&&f[7]>.5)p[m]=-100.f;
            else if(g.units[id].team!=g.me)p[m]=infer<learning::PF,std::size(weights::opponent_b0),std::size(weights::opponent_b1)>(f,weights::opponent_w0,weights::opponent_b0,weights::opponent_w1,weights::opponent_b1,weights::opponent_w2,weights::opponent_b2);
            else p[m]=infer<learning::PF,std::size(weights::policy_b0),std::size(weights::policy_b1)>(f,weights::policy_w0,weights::policy_b0,weights::policy_w1,weights::policy_b1,weights::policy_w2,weights::policy_b2);
            maximum=std::max(maximum,p[m]);
        }
        for(float& q:p){q=std::exp((q-maximum)/1.05f);sum+=q;}
        for(float& q:p)q/=sum;return p;
    }
    std::array<float,NO> opponentLogits(const std::array<float,learning::PF>& x)const{
        constexpr int H=std::size(weights::opponent_b0),Z=std::size(weights::opponent_b1);
        static_assert(NO==std::size(weights::opponent_b2));
        float h[H],z[Z];std::array<float,NO> out{};
        for(int j=0;j<H;j++)h[j]=std::max(0.f,weights::opponent_b0[j]+dot<learning::PF>(x.data(),weights::opponent_w0+j*learning::PF));
        for(int j=0;j<Z;j++)z[j]=std::max(0.f,weights::opponent_b1[j]+dot<H>(h,weights::opponent_w1+j*H));
        for(int j=0;j<NO;j++)out[j]=weights::opponent_b2[j]+dot<Z>(z,weights::opponent_w2+j*Z);
        return out;
    }
    std::array<Prob,E> experts(const Game& g,int id){
        std::array<Prob,E> model{};auto& u=g.units[id];int start=geo.cell(u);
        if(start<0){for(auto& p:model)p[0]=1;return model;}
        if constexpr(NN==1&&AK==0)model[0]=policy(g,id);
        else{
            std::array<std::array<float,learning::PF>,5> all{};
            if constexpr(NN_BATCH_FEATURES)all=geo.policyMoves(g,id,previous[id]);
            // One shared trunk per move, with small linear style heads.
            for(int m=0;m<5;m++){
                auto f=NN_BATCH_FEATURES?all[m]:geo.policy(g,id,m,previous[id]);auto pred=opponentLogits(f);
                for(int k=0;k<NN;k++)model[k][m]=m&&f[7]>.5?-100.f:pred[k];
                if constexpr(AK){
                    for(int k=0;k<NN;k++){
                        auto& action=actionForecast[id][m][k];float maximum=-1e9f,sum=0;
                        for(int a=0;a<AK;a++){action[a]=pred[NN+k*AK+a];maximum=std::max(maximum,action[a]);}
                        for(float& q:action){q=std::exp(q-maximum);sum+=q;}for(float& q:action)q/=sum;
                    }
                }
            }
            for(int k=0;k<NN;k++){
                float maximum=*std::max_element(model[k].begin(),model[k].end()),sum=0;
                for(float& q:model[k]){q=std::exp((q-maximum)/1.05f);sum+=q;}for(float& q:model[k])q/=sum;
            }
        }
        int goal=-1;float best=1e9f;
        for(auto& f:g.flags){int q=f.x>=0&&(f.return_at<0||f.return_at>g.turn)?f.y*g.size+f.x:-1;if(q>=0){float cost=geo.D(start,q)+.15f*geo.home[u.team][q];if(cost<best){best=cost;goal=q;}}}
        if(goal<0)for(auto s:g.spots){int q=s.second*g.size+s.first;float cost=geo.D(start,q)+.35f*geo.home[u.team][q];if(cost<best){best=cost;goal=q;}}
        int victim=-1;float bv=-1e9f;
        for(auto& e:g.units)if(e.team!=u.team&&e.x>=0&&geo.man(start,geo.cell(e))<=6){float v=(e.flag>=0?5.f:0.f)+(100-e.hp)*.03f-geo.D(start,geo.cell(e));if(v>bv){bv=v;victim=e.id;}}
        for(int modelId=NN;modelId<E;modelId++){
            int behavior=modelId-NN+1;
            float maximum=-1e9f,sum=0;
            for(int m=0;m<5;m++){
                int p=geo.nb[start][m];float progress=u.flag>=0?geo.home[u.team][start]-geo.home[u.team][p]:geo.D(start,goal)-geo.D(p,goal),danger=0,attack=0;
                for(auto& e:g.units)if(e.team!=u.team&&e.x>=0){int q=geo.cell(e),d=geo.man(p,q);if(e.flag<0)danger+=d<=2?1.f:d==3?.45f:0.f;attack=std::max(attack,geo.hit(g,p,q)?(e.flag>=0?3.f:e.hp<=34?2.f:1.f):0.f);}
                float score=2.4f*progress-.1f*(m==0);
                if(behavior==2&&u.flag<0&&victim>=0)score=geo.hit(g,start,geo.cell(g.units[victim]))?(m==0?3.f:attack):1.4f*(geo.D(start,geo.cell(g.units[victim]))-geo.D(p,geo.cell(g.units[victim])))+attack;
                if(behavior==3&&u.flag<0){score=1.1f*progress+2.2f*attack-.3f*danger;if(victim>=0)score+=.8f*(geo.D(start,geo.cell(g.units[victim]))-geo.D(p,geo.cell(g.units[victim])));}
                if(behavior==4)score=1.8f*progress-(u.flag>=0?3.f:u.hp<=34?2.5f:1.5f)*danger;
                if(behavior==5)score=0;
                if(m&&p==start)score=-100;model[modelId][m]=score;maximum=std::max(maximum,score);
            }
            for(float& q:model[modelId]){q=std::exp(q-maximum);sum+=q;}for(float& q:model[modelId])q/=sum;
        }return model;
    }
    std::vector<Prob> predict(const Game& g,bool save=false){
        std::vector<Prob> p(g.units.size());std::array<float,E> prior{};
        for(int k=0;k<NN;k++)prior[k]=.70f/NN;
        const float fallback[5]={.08f,.06f,.06f,.08f,.02f};for(int k=0;k<5;k++)prior[NN+k]=fallback[k];
        for(auto& u:g.units){
            if(u.team==g.me){p[u.id]=policy(g,u.id);continue;}
            auto model=experts(g,u.id);float w[E],sum=0,maximum=-1e9f;int category=u.flag>=0;
            for(int k=0;k<E;k++)maximum=std::max(maximum,evidence[u.team][category][k]+std::log(prior[k]));
            for(int k=0;k<E;k++){w[k]=std::exp(evidence[u.team][category][k]+std::log(prior[k])-maximum);sum+=w[k];}
            for(int k=0;k<E;k++)for(int m=0;m<5;m++)p[u.id][m]+=w[k]/sum*model[k][m];
            if constexpr(NN_JOINT_BELIEF||AK)workingExperts[u.id]=model;
            if constexpr(AK)for(int k=0;k<E;k++)headPosterior[u.id][k]=w[k]/sum;
            if(save){lastExperts[u.id]=model;lastClass[u.id]=category;if constexpr(NN_ACTION_EVIDENCE&&AK)lastActionForecast[u.id]=actionForecast[u.id];}
        }return p;
    }
    void adapt(const Game& g){
        std::array<bool,45> motionUsed{};
        for(auto& u:g.units)if(u.team!=g.me&&u.x>=0&&previous[u.id]>=0){int now=geo.cell(u),old=previous[u.id];if(geo.man(now,old)>1)continue;
            motionUsed[u.id]=true;
            bool blocked=false;for(auto& a:g.units)if(a.id!=u.id&&a.x>=0&&geo.man(old,geo.cell(a))<=1)blocked=true;
            for(int k=0;k<E;k++){float likelihood=0;for(int m=0;m<5;m++)if(geo.nb[old][m]==now)likelihood+=lastExperts[u.id][k][m];if(blocked&&now==old)likelihood=.15f+.85f*likelihood;
                auto& v=evidence[u.team][lastClass[u.id]][k];v=.992f*v+.09f*std::log(.025f+.975f*likelihood);
            }
        }
        if constexpr(NN_ACTION_EVIDENCE&&AK){
            std::array<int,45> seen,position;seen.fill(-1);position.fill(-1);
            for(auto& u:g.units)position[u.id]=geo.cell(u);
            for(auto& event:g.events)if(!event.args.empty()){
                int id=event.args[0];if(id<0||id>=int(g.units.size()))continue;
                if(event.type=="attack")seen[id]=1;
                else if(event.type=="pickup")seen[id]=0;
                else if(event.type=="drop")seen[id]=3;
                else if(event.type=="death"&&event.args.size()>=3)position[id]=event.args[2]*g.size+event.args[1];
            }
            for(auto& u:g.units)if(u.team!=g.me&&previous[u.id]>=0&&position[u.id]>=0){
                int old=previous[u.id],now=position[u.id];if(geo.man(old,now)>1)continue;
                bool blocked=false,contact=false,refused=false;
                for(auto& a:g.units){
                    if(a.id!=u.id&&a.x>=0&&geo.man(old,geo.cell(a))<=1)blocked=true;
                    if(a.team!=u.team&&position[a.id]>=0&&!newLife[a.id]&&geo.hit(g,now,position[a.id]))contact=true;
                }
                contact=contact&&lastClass[u.id]==0&&!newLife[u.id];
                if(u.x>=0&&u.flag<0&&lastClass[u.id]==0)for(auto& flag:g.flags)if(flag.x>=0&&flag.y*g.size+flag.x==now)refused=true;
                if(seen[u.id]<0&&!contact&&!refused)continue;
                for(int head=0;head<E;head++){
                    float joint=0,mass=0,unconditional=0;
                    for(int m=0;m<5;m++){
                        std::array<float,AK> ap{};
                        if(head<NN)ap=lastActionForecast[u.id][m][head];
                        else{ap[0]=lastClass[u.id]?.4875f:.475f;ap[1]=lastClass[u.id]?0.f:.475f;ap[2]=lastClass[u.id]?.4875f:.025f;ap[3]=.025f;}
                        // A missing event is censored: even an intended shot
                        // can miss. Positive events expose the action exactly.
                        float likelihood=seen[u.id]>=0?ap[seen[u.id]]:1.f-(contact?.65f*ap[1]:0.f)-(refused?ap[0]:0.f);
                        likelihood=std::clamp(likelihood,0.f,1.f);
                        float move=lastExperts[u.id][head][m];unconditional+=move*likelihood;
                        if(geo.nb[old][m]==now){joint+=move*likelihood;mass+=move;}
                    }
                    if(blocked&&now==old){joint=.15f*unconditional+.85f*joint;mass=.15f+.85f*mass;}
                    float likelihood=std::clamp(joint/std::max(.000001f,mass),0.f,1.f);
                    auto& v=evidence[u.team][lastClass[u.id]][head];if(!motionUsed[u.id])v*=.992f;
                    v+=.09f*std::log(.025f+.975f*likelihood);
                }
            }
        }
    }
    float random(){rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;return (rng>>40)*(1.f/16777216);}
    int sample(const Prob& p){float r=random();for(int m=0;m<4;m++){r-=p[m];if(r<0)return m;}return 4;}
    std::vector<Candidate> moves(const Game& g,int team,const std::vector<Prob>& prob)const{
        std::vector<Candidate> out;int start[3];for(int k=0;k<3;k++)start[k]=geo.cell(g.units[team*3+k]);
        for(int a=0;a<5;a++)for(int b=0;b<5;b++)for(int c=0;c<5;c++){
            Candidate ca;ca.moves={a,b,c};int p[3];bool valid=true;
            for(int k=0;k<3;k++){int id=team*3+k,m=ca.moves[k];if(prob[id][m]<.00005f){valid=false;break;}p[k]=start[k]<0?-1:geo.nb[start[k]][m];ca.prior+=std::log(std::max(.00001f,prob[id][m]));}
            if(!valid)continue;
            for(int k=0;k<3;k++)for(int l=k+1;l<3;l++)if(p[k]>=0&&p[k]==p[l])valid=false;
            if(valid)out.push_back(ca);
        }
        if(out.empty()){Candidate c;out.push_back(c);}
        std::sort(out.begin(),out.end(),[](const auto& a,const auto& b){return a.prior>b.prior;});return out;
    }
    std::array<int,3> shots(const Game& g,int team,const Joint& move,const std::vector<Prob>& prob,bool pickupCost=true,int willing=7)const{
        int p[3],can=0;float pickup[3]={};
        for(int k=0;k<3;k++){
            auto& u=g.units[team*3+k];int q=geo.cell(u);p[k]=q<0?-1:geo.nb[q][move[k]];
            if(q>=0&&u.flag<0&&!(g.turn==preparedTurn&&newLife[u.id]))can|=1<<k;
            if(pickupCost&&q>=0&&u.flag<0)for(auto& f:g.flags)if(f.x>=0&&(f.return_at<0||f.return_at>g.turn)&&f.y*g.size+f.x==p[k])pickup[k]=geo.home[team][p[k]]==0?1.2f:.32f;
        }
        can&=willing;
        float dp[8];std::array<int,3> action[8];
        std::fill(dp,dp+8,-1e9f);dp[0]=0;for(auto& a:action)a={-1,-1,-1};
        for(auto& e:g.units)if(e.team!=team&&e.x>=0&&!(g.turn==preparedTurn&&newLife[e.id])){
            int q=geo.cell(e),need=(e.hp+g.damage-1)/g.damage;float reward[8]={};
            for(int mask=1;mask<8;mask++)if((mask&can)==mask){
                for(int m=0;m<5;m++){
                    int z=geo.nb[q][m],hits=0;for(int k=0;k<3;k++)if((mask>>k&1)&&geo.hit(g,p[k],z))hits++;
                    float kill=hits>=need?1.f:0.f;
                    reward[mask]+=prob[e.id][m]*(.045f*std::min(need,hits)+kill*(e.flag>=0?.65f:.20f));
                }
                for(int k=0;k<3;k++)if(mask>>k&1)reward[mask]-=pickup[k];
            }
            for(int mask=7;mask>=0;mask--)if(dp[mask]>-1e8f){int left=can&~mask;
                for(int sub=left;sub;sub=(sub-1)&left){int next=mask|sub;float v=dp[mask]+reward[sub];if(v>dp[next]){dp[next]=v;action[next]=action[mask];for(int k=0;k<3;k++)if(sub>>k&1)action[next][k]=e.id;}}
            }
        }
        int best=0;for(int mask=1;mask<8;mask++)if(dp[mask]>dp[best])best=mask;return action[best];
    }
    std::vector<Order> enemyOrders(const Game& g,const std::vector<Prob>& prob,bool stochastic,const std::array<int,15>* fixedHeads=nullptr){
        std::vector<Order> out(g.units.size());
        sampledHeads.fill(-1);std::vector<Prob> conditional;
        if constexpr(NN_JOINT_BELIEF)conditional=prob;
        const auto& movementProb=NN_JOINT_BELIEF?conditional:prob;
        if constexpr(NN_JOINT_BELIEF){
            if(stochastic)for(int team=0;team<g.teams;team++)if(team!=g.me){
                int chosen=fixedHeads?(*fixedHeads)[team]:-1;
                if(chosen<0){
                    std::array<float,E> w{};float maximum=-1e9f,sum=0;
                    const float fallback[5]={.08f,.06f,.06f,.08f,.02f};
                    for(int k=0;k<E;k++){
                        float likelihood=0;int alive=0;
                        for(int id=team*3;id<team*3+3;id++)if(g.units[id].x>=0){likelihood+=evidence[team][g.units[id].flag>=0][k];alive++;}
                        if(alive)likelihood/=alive;else likelihood=evidence[team][0][k];
                        w[k]=likelihood+std::log(k<NN?.70f/NN:fallback[k-NN]);maximum=std::max(maximum,w[k]);
                    }
                    for(float& x:w){x=std::exp(x-maximum);sum+=x;}
                    float r=random()*sum;chosen=E-1;for(int k=0;k<E-1;k++){r-=w[k];if(r<0){chosen=k;break;}}
                }
                sampledHeads[team]=chosen;
                for(int id=team*3;id<team*3+3;id++)conditional[id]=workingExperts[id][chosen];
            }
        }
        for(int team=0;team<g.teams;team++)if(team!=g.me){
            auto options=moves(g,team,movementProb);Joint mv=options[0].moves;
            if(stochastic){
                for(int k=0;k<3;k++)mv[k]=sample(movementProb[team*3+k]);
                int p[3];for(int k=0;k<3;k++){int s=geo.cell(g.units[team*3+k]);p[k]=s<0?-1:geo.nb[s][mv[k]];}
                bool collision=false;for(int k=0;k<3;k++)for(int l=k+1;l<3;l++)if(p[k]>=0&&p[k]==p[l])collision=true;
                if(collision)mv=options[0].moves;
            }
            auto ac=shots(g,team,mv,prob);
            if constexpr(AK){
                std::array<int,3> kinds{};int willing=0;
                for(int k=0;k<3;k++){
                    int id=team*3+k,m=mv[k];if(g.units[id].x<0)continue;
                    std::array<float,AK> ap{};float total=0;
                    for(int head=0;head<E;head++){
                        float weight=sampledHeads[team]>=0?(head==sampledHeads[team]?1.f:0.f):headPosterior[id][head]*workingExperts[id][head][m];
                        total+=weight;
                        if(head<NN)for(int a=0;a<AK;a++)ap[a]+=weight*actionForecast[id][m][head][a];
                        else ap[ac[k]>=0?1:0]+=weight;
                    }
                    if(total<=1e-8f)ap[ac[k]>=0?1:0]=total=1;
                    for(float& q:ap)q/=total;
                    int kind=std::max_element(ap.begin(),ap.end())-ap.begin();
                    if(stochastic){float r=random();kind=AK-1;for(int a=0;a<AK-1;a++){r-=ap[a];if(r<0){kind=a;break;}}}
                    kinds[k]=kind;if(kind==1)willing|=1<<k;
                }
                auto fire=shots(g,team,mv,prob,false,willing);
                for(int k=0;k<3;k++)ac[k]=kinds[k]==0?-1:kinds[k]==1?(fire[k]>=0?fire[k]:-2):kinds[k]==3?-3:-2;
            }
            for(int k=0;k<3;k++)out[team*3+k]={mv[k],ac[k]};
        }
        return out;
    }
    Game step(const Game& g,const Candidate& ca,const std::vector<Order>& enemy,uint64_t seed)const{
        auto orders=enemy;for(int k=0;k<3;k++)orders[g.me*3+k]={ca.moves[k],ca.actions[k]};
        World world(g,seed);world.g.turn=g.turn-1;world.step(orders);world.g.turn=g.turn+1;return world.g;
    }
    float reward(const Game& before,const Game& after)const{
        float r=after.score[before.me]-before.score[before.me],other=0;
        for(int t=0;t<before.teams;t++)if(t!=before.me)other+=after.score[t]-before.score[t];
        if constexpr(NN_LEADER_OBJECTIVE){
            int oldLeader=0,newLeader=0;
            for(int t=0;t<before.teams;t++)if(t!=before.me){oldLeader=std::max(oldLeader,before.score[t]);newLeader=std::max(newLeader,after.score[t]);}
            r-=newLeader-oldLeader;
        }else r-=(before.teams==2?1.f:.5f)*other/(before.teams-1);
        if(after.turn<=before.turns)for(auto& u:before.units)if(u.x>=0&&after.units[u.id].x<0)r+=u.team==before.me?-.025f:.025f/(before.teams-1);
        return r;
    }
    Candidate rollout(const Game& g,const std::vector<Prob>& prob)const{
        auto ca=moves(g,g.me,prob)[0];ca.actions=shots(g,g.me,ca.moves,prob);return ca;
    }
    std::string run(const Game& g){
        auto started=std::chrono::steady_clock::now();deadline=started+std::chrono::milliseconds(g.turn==1?1600:12);
        if(!geo.n){geo.init(g);previous.assign(g.units.size(),-1);}
        adapt(g);auto observation=learning::prepared(g);preparedTurn=g.turn;newLife.assign(g.units.size(),false);
        for(auto& u:observation.units)newLife[u.id]=g.units[u.id].x<0&&u.x>=0;
        auto prob=predict(observation,true);auto options=moves(observation,g.me,prob);
        // Compute shots only for the joint moves the search will actually visit.
        // Most of the 125 legal combinations would otherwise be discarded.
        for(int c=0;c<std::min(32,int(options.size()));c++)options[c].actions=shots(observation,g.me,options[c].moves,prob);
        Candidate best=options[0];
#ifndef NN_SEARCH
#define NN_SEARCH 1
#endif
        if(NN_SEARCH&&g.turn<=g.turns){
            const int samples=4,width=32,beam=5;
            std::array<std::vector<Order>,samples> opponent;
            std::array<std::array<int,15>,samples> headScenario{};
            for(int s=0;s<samples;s++){opponent[s]=enemyOrders(observation,prob,s>0);headScenario[s]=sampledHeads;}
            auto now=std::chrono::steady_clock::now();
            auto rootDeadline=now+(deadline-now)*3/5;
            std::vector<Candidate> evaluated;
            for(int c=0;c<std::min(width,int(options.size()));c++){
                if(c>0&&std::chrono::steady_clock::now()>rootDeadline)break;
                auto ca=options[c];float sum=0,worst=1e9f;
                for(int s=0;s<samples;s++){
                    auto next=step(g,ca,opponent[s],uint64_t(g.turn*7919+s*65537+g.me*101+7));
                    float v=reward(g,next)+.97f*value(next,g.me);sum+=v/samples;worst=std::min(worst,v);
                }
                ca.value=.9f*sum+.1f*worst+.025f*ca.prior;
                evaluated.push_back(ca);if(ca.value>best.value)best=ca;
            }
            std::sort(evaluated.begin(),evaluated.end(),[](auto a,auto b){return a.value>b.value;});
#ifndef NN_ACTION_REFINEMENT
#define NN_ACTION_REFINEMENT 0
#endif
            if(NN_ACTION_REFINEMENT){
                // Let the learned state value decide whether to pick up a
                // flag, keep fighting over it, or release a carried flag.
                // These legal actions were absent from movement-only search.
                std::vector<Candidate> alternate;
                for(int c=0;c<std::min(3,int(evaluated.size()));c++){
                    auto ca=evaluated[c];auto attack=shots(observation,g.me,ca.moves,prob,false);
                    if(attack!=ca.actions){auto other=ca;other.actions=attack;alternate.push_back(other);}
                    for(int k=0;k<3;k++)if(observation.units[g.me*3+k].flag>=0){auto other=ca;other.actions[k]=-3;alternate.push_back(other);}
                }
                for(auto ca:alternate){
                    if(std::chrono::steady_clock::now()>deadline-std::chrono::milliseconds(4))break;
                    float sum=0,worst=1e9f;
                    for(int s=0;s<samples;s++){
                        auto next=step(g,ca,opponent[s],uint64_t(g.turn*7919+s*65537+g.me*101+7));
                        float v=reward(g,next)+.97f*value(next,g.me);sum+=v/samples;worst=std::min(worst,v);
                    }
                    ca.value=.9f*sum+.1f*worst+.025f*ca.prior;
                    evaluated.push_back(ca);if(ca.value>best.value)best=ca;
                }
                std::sort(evaluated.begin(),evaluated.end(),[](auto a,auto b){return a.value>b.value;});
            }
            float deepBest=-1e9f;
            for(int c=0;c<std::min(beam,int(evaluated.size()));c++){
                if(std::chrono::steady_clock::now()>deadline-std::chrono::milliseconds(3))break;
                auto ca=evaluated[c];float sum=0;
                for(int s=0;s<2;s++){
                    auto next=step(g,ca,opponent[s],uint64_t(g.turn*7919+s*65537+g.me*101+7));
                    float r=reward(g,next);
                    if(next.turn<=g.turns){
                        // Future decisions observe the movement just simulated,
                        // not the history two real turns before the rollout.
                        auto savedHistory=previous;auto savedLife=newLife;int savedTurn=preparedTurn;
                        for(auto& u:observation.units)previous[u.id]=geo.cell(u);
                        auto futureObservation=learning::prepared(next);preparedTurn=next.turn;
                        for(auto& u:futureObservation.units)newLife[u.id]=next.units[u.id].x<0&&u.x>=0;
                        auto pp=predict(futureObservation);auto action=rollout(futureObservation,pp);auto eo=enemyOrders(futureObservation,pp,s>0,NN_JOINT_BELIEF?&headScenario[s]:nullptr);
                        previous=savedHistory;newLife=savedLife;preparedTurn=savedTurn;
                        auto leaf=step(next,action,eo,uint64_t(g.turn*6547+s*31+11));
                        r+=.97f*reward(next,leaf)+.9409f*value(leaf,g.me);
                    }else r+=.97f*value(next,g.me);
                    sum+=r*.5f;
                }
                float score=.65f*(sum+.025f*ca.prior)+.35f*ca.value;
                if(score>deepBest){deepBest=score;best=ca;}
            }
        }
        std::string out=std::to_string(g.turn);for(int k=0;k<3;k++){int id=g.me*3+k;out+=' ';out+=std::string("SUDLR")[best.moves[k]];out+=' ';out+=best.actions[k]==-3?"X":g.units[id].flag>=0?"-":best.actions[k]>=0?std::to_string(best.actions[k]):"P";}
        for(auto& u:g.units)previous[u.id]=geo.cell(u);return out;
    }
};
int main(){std::ios::sync_with_stdio(false);std::cin.tie(nullptr);Game g;Planner p;while(read_turn(g))std::cout<<p.run(g)<<std::endl;return 0;}
